import { InputComponent } from './input.component';
const meta = {
    title: 'Components/Input',
    component: InputComponent,
    tags: ['autodocs'],
    argTypes: {
        type: {
            control: 'select',
            options: ['text', 'email', 'password', 'number', 'search', 'tel'],
        },
        size: {
            control: 'select',
            options: ['sm', 'md', 'lg'],
        },
        hasError: { control: 'boolean' },
        disabled: { control: 'boolean' },
        label: { control: 'text' },
        placeholder: { control: 'text' },
        errorMessage: { control: 'text' },
        hint: { control: 'text' },
    },
};
export default meta;
export const Default = {
    args: {
        label: 'Full name',
        placeholder: 'Enter your name',
        size: 'md',
    },
};
export const WithHint = {
    args: {
        label: 'Username',
        placeholder: 'e.g. john_doe',
        hint: 'Only letters, numbers and underscores.',
        size: 'md',
    },
};
export const WithError = {
    args: {
        label: 'Email',
        placeholder: 'you@example.com',
        type: 'email',
        hasError: true,
        errorMessage: 'Please enter a valid email address.',
        size: 'md',
    },
};
export const Password = {
    args: {
        label: 'Password',
        placeholder: '••••••••',
        type: 'password',
        size: 'md',
    },
};
export const Disabled = {
    args: {
        label: 'API key',
        placeholder: 'sk-...',
        disabled: true,
        size: 'md',
    },
};
export const NoLabel = {
    args: {
        placeholder: 'Search…',
        type: 'search',
        size: 'md',
    },
};
export const Sizes = {
    render: () => ({
        template: `
      <div style="display:flex;flex-direction:column;gap:12px;max-width:320px;padding:8px;">
        <dsb-input label="Small" placeholder="Small input" size="sm"></dsb-input>
        <dsb-input label="Medium" placeholder="Medium input" size="md"></dsb-input>
        <dsb-input label="Large" placeholder="Large input" size="lg"></dsb-input>
      </div>`,
    }),
};
